<?php
require_once __DIR__ . '/../app/layout.php';require_login();$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{
 $copy=(int)($_POST['copy_id']??0);$type=(string)($_POST['movement_type']??'');$reason=trim((string)($_POST['reason']??''));
 $allowed=['entry','transfer_in','transfer_out','disposal','loss','damage','repair','adjustment'];
 if(!$copy||!in_array($type,$allowed,true)||$reason==='')throw new RuntimeException('Choose a copy, movement type and provide a reason.');
 $pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM book_copies WHERE id=? FOR UPDATE');$s->execute([$copy]);$c=$s->fetch();if(!$c)throw new RuntimeException('Copy not found.');
 $newStatus=$c['status'];
 if(in_array($type,['transfer_out','disposal','loss'],true)){
  $active=$pdo->prepare('SELECT COUNT(*) FROM loans WHERE copy_id=? AND returned_at IS NULL');$active->execute([$copy]);if((int)$active->fetchColumn())throw new RuntimeException('Return the copy before recording an exit movement.');
  $newStatus=$type==='loss'?'lost':'withdrawn';
 }elseif($type==='damage')$newStatus='damaged';elseif($type==='repair')$newStatus='repair';elseif(in_array($type,['entry','transfer_in'],true))$newStatus='available';
 $pdo->prepare('UPDATE book_copies SET status=?,condition_note=? WHERE id=?')->execute([$newStatus,$reason,$copy]);
 $s=$pdo->prepare('INSERT INTO stock_movements(copy_id,movement_type,movement_date,source_destination,reason,reference_no,handled_by,notes) VALUES(?,?,NOW(),?,?,?,?,?)');
 $s->execute([$copy,$type,trim((string)($_POST['destination']??''))?:null,$reason,trim((string)($_POST['reference_no']??''))?:null,(int)$_SESSION['user_id'],trim((string)($_POST['notes']??''))?:null]);
 $pdo->commit();flash('success','Stock movement recorded. Current copy status: '.$newStatus.'.');redirect('movements.php');
}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'Could not record movement. Please check the selected copy.';}}
$copies=$pdo->query("SELECT c.id,c.accession_code,c.status,b.title FROM book_copies c JOIN books b ON b.id=c.book_id ORDER BY b.title,c.accession_code")->fetchAll();
$rows=$pdo->query("SELECT sm.*,c.accession_code,b.title,u.name staff_name FROM stock_movements sm JOIN book_copies c ON c.id=sm.copy_id JOIN books b ON b.id=c.book_id JOIN users u ON u.id=sm.handled_by ORDER BY sm.id DESC LIMIT 300")->fetchAll();
page_start('Entry & exit register');if($error)echo '<div class="alert error">'.e($error).'</div>';
echo '<div class="grid two-col"><section class="card"><div class="section-head"><div><h2>Record a movement</h2><p>Use for physical stock changes, not ordinary borrowing</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><div class="form-grid"><div class="field full"><label>Book copy *</label><select name="copy_id" required><option value="">Select copy</option>';foreach($copies as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['title'].' — '.$c['accession_code'].' ('.$c['status'].')').'</option>';echo '</select></div><div class="field"><label>Movement type *</label><select name="movement_type" required><option value="entry">Entry / received</option><option value="transfer_in">Transfer in</option><option value="transfer_out">Transfer out</option><option value="disposal">Disposal / withdrawn</option><option value="loss">Lost</option><option value="damage">Damaged</option><option value="repair">Sent for repair</option><option value="adjustment">Stock adjustment</option></select></div><div class="field"><label>Reference / voucher</label><input name="reference_no" maxlength="80"></div><div class="field full"><label>Reason *</label><input name="reason" required maxlength="255" placeholder="e.g. donated by community member"></div><div class="field full"><label>Source / destination</label><input name="destination" maxlength="190" placeholder="Supplier, donor, branch or destination"></div><div class="field full"><label>Notes</label><textarea name="notes" rows="2"></textarea></div></div><div class="notice">Exit movements for a currently issued copy are blocked. Disposals, transfers and losses update the copy status.</div><div class="form-actions"><button class="btn btn-primary">Save movement</button></div></form></section><section class="card"><div class="section-head"><div><h2>Movement guide</h2><p>Keep each change explainable and traceable</p></div></div><div class="notice"><b>Entry</b><br>Record incoming stock after verifying the copy and accession details.</div><div class="notice"><b>Transfer out / disposal / loss</b><br>Removes a copy from normal circulation. Keep the reason and destination/reference.</div><div class="notice"><b>Damage / repair</b><br>Marks the copy unavailable until staff assess and restore it.</div><div class="notice"><b>Adjustment</b><br>Use for reconciliation with a documented explanation. Restrict this to authorized roles in the production version.</div></section></div><section class="card" style="margin-top:18px"><div class="section-head"><div><h2>Stock movement history</h2><p>Latest entry and exit events</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Book / copy</th><th>Type</th><th>Reason</th><th>Destination</th><th>Handled by</th></tr></thead><tbody>';
if(!$rows)echo '<tr><td colspan="6" class="empty">No stock movements recorded yet.</td></tr>';
foreach($rows as $r)echo '<tr><td>'.e(substr($r['movement_date'],0,16)).'</td><td><span class="book-title">'.e($r['title']).'</span><span class="subtext">'.e($r['accession_code']).'</span></td><td><span class="badge issued">'.e(str_replace('_',' ',ucfirst($r['movement_type']))).'</span></td><td>'.e($r['reason']).'</td><td>'.e($r['source_destination']??'—').'</td><td>'.e($r['staff_name']).'</td></tr>';
echo '</tbody></table></div></section>';
page_end();
